test('lineTotal: calculates qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
});

test('lineTotal: handles large quantities', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 100000 }), 100000000);
});

test('lineTotal: returns integer cents', () => {
  const result = lineTotal({ qty: 3, unitPrice: 6500 });
  assert(Number.isInteger(result));
  assert.equal(result, 19500);
});

test('invoiceTotals: single line invoice', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.total, 47500);
});

test('invoiceTotals: multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500 }, // 47500
      { qty: 1, unitPrice: 120000 }, // 120000
      { qty: 100, unitPrice: 50 }, // 5000
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 172500);
  assert.equal(totals.total, 172500);
});

test('invoiceTotals: empty invoice', () => {
  const invoice = { lines: [] };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals: returns integers', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100 },
      { qty: 2, unitPrice: 200 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert(Number.isInteger(totals.subtotal));
  assert(Number.isInteger(totals.total));
});

test('invoiceTotals: with invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 }, // 10 * 9500 = 95000
      { sku: 'DES-HOUR', qty: 5 }, // 5 * 8500 = 42500
    ],
  });

  assert(result.ok);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.total, 137500);
});

test('invoiceTotals: does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500 }],
  };
  const originalInvoice = JSON.parse(JSON.stringify(invoice));

  invoiceTotals(invoice);

  assert.deepEqual(invoice, originalInvoice);
});

